using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    string out;
    out.reserve(14000000);
    char num[16];
    for (int i = 1; i <= n; i++) {
        // 15 first, then 3, then 5: the branches are mutually exclusive.
        if (i % 15 == 0) out += "FizzBuzz";
        else if (i % 3 == 0) out += "Fizz";
        else if (i % 5 == 0) out += "Buzz";
        else { int len = snprintf(num, sizeof num, "%d", i); out.append(num, len); }
