    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringBuilder out = new StringBuilder(14_000_000);
        for (int i = 1; i <= n; i++) {
            // 15 first, then 3, then 5: the branches are mutually exclusive.
            if (i % 15 == 0) out.append("FizzBuzz");
            else if (i % 3 == 0) out.append("Fizz");
            else if (i % 5 == 0) out.append("Buzz");
            else out.append(i);
            out.append('\n');
        }
        PrintStream ps = new PrintStream(new BufferedOutputStream(System.out, 1 << 16), false);
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"fmt"
	"os"
	"strconv"
)

func main() {
	var n int
	fmt.Scan(&n)
	out := make([]byte, 0, 14000000)
	for i := 1; i <= n; i++ {
		// 15 first, then 3, then 5: the branches are mutually exclusive.
		switch {
		case i%15 == 0:
			out = append(out, "FizzBuzz"...)
		case i%3 == 0:
			out = append(out, "Fizz"...)
		case i%5 == 0:
			out = append(out, "Buzz"...)
		default:
			out = strconv.AppendInt(out, int64(i), 10)
		}
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
